<?php
require_once dirname(__DIR__, 2) . '/comun/autoload.php';
require_once SGA_COMUN_SERVER . '/conexion.php';
require_once __DIR__ . '/lib/FormatosService.php';

formatos_require_access();
$error = '';
$notice = '';
try {
    formatos_ensure_schema($mysqli);
    $ctx = formatos_context($mysqli);
    $observerCtx = $ctx;
    if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST' && ($_POST['accion'] ?? '') === 'guardar_observador') {
        formatos_save_observer($mysqli, $observerCtx, (string)$_POST['estudiante'], $_POST['observador'] ?? [], (string)($_POST['observaciones'] ?? ''), (string)$_SESSION['id_usuario']);
        $notice = 'Los indicadores y observaciones del período activo quedaron guardados.';
    }
    if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST' && ($_POST['accion'] ?? '') === 'guardar_perfil') {
        formatos_save_profile($mysqli, (string)$_POST['estudiante'], $_POST);
        $notice = 'Los datos complementarios del estudiante fueron actualizados.';
    }
    if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST' && ($_POST['accion'] ?? '') === 'guardar_desercion') {
        formatos_save_dropout_actions($mysqli, $ctx, $_POST['acciones'] ?? [], (string)$_SESSION['id_usuario']);
        $notice = 'Las acciones de seguimiento fueron guardadas.';
    }
    $students = formatos_students($mysqli, $ctx);
    $studentId = trim((string)($_GET['estudiante'] ?? $_POST['estudiante'] ?? ($students[0]['id_usuario'] ?? '')));
    $student = $studentId ? formatos_student($mysqli, $ctx, $studentId) : null;
    $observer = $student ? formatos_observer_data($mysqli, $observerCtx, $studentId) : ['items'=>[], 'observaciones'=>''];
    $dropouts = formatos_dropouts($mysqli, $ctx);
    $recovery = formatos_recovery_rows($mysqli, $ctx);
    $academicCandidates = array_map(function ($row) {
        return ['id_usuario' => $row['id_usuario'], 'estudiante' => formatos_full_name($row), 'grado' => $row['grado']];
    }, $students);
    $staff = formatos_rows($mysqli, "SELECT id_usuario, nombre, apellido, rol FROM usuario WHERE rol REGEXP 'admin|directivo|docente' AND LOWER(TRIM(COALESCE(estado, 'activo'))) = 'activo' ORDER BY apellido, nombre");
} catch (Throwable $e) {
    $error = $e->getMessage(); $ctx = ['ano'=>'Sin configurar', 'periodo'=>0, 'nombre_periodo'=>'Sin configurar'];
    $students = $dropouts = $recovery = $academicCandidates = $staff = []; $student = null; $observer = ['items'=>[], 'observaciones'=>'']; $observerCtx = $ctx;
}
$studentName = $student ? formatos_full_name($student) : 'Selecciona un estudiante';
?>
