ame="registro[<?php echo formatos_e($key); ?>][grupo]" value="<?php echo formatos_e($row['grupo']); ?>"><input type="hidden" name="registro[<?php echo formatos_e($key); ?>][jornada]" value="<?php echo formatos_e($row['jornada']); ?>"><input type="hidden" name="registro[<?php echo formatos_e($key); ?>][materia]" value="<?php echo formatos_e($row['materia']); ?>"></td><td><?php echo formatos_e($row['grado']); ?></td><td><?php echo formatos_e($row['grupo'] ?: '—'); ?></td><td><?php echo formatos_e($row['jornada'] ?: '—'); ?></td><td><?php echo formatos_e($row['materia']); ?></td><td><span class="text-danger fw-bold"><?php echo number_format((float)$row['nota'], 1); ?></span></td><td><input class="form-control form-control-sm" name="registro[<?php echo formatos_e($key); ?>][competencia]" placeholder="Competencia o logro a fortalecer"></td></tr><?php endforeach; ?></tbody></table></div><div class="sticky-actions mt-4"><button class="btn btn-brand"><i class="bi bi-file-earmark-word me-1"></i>Descargar planilla Word</button></div><?php else: ?><div class="empty"><i class="bi bi-clipboard2-check"></i><p class="mb-0 mt-2">No existen notas inferiores a 3,0 en la auditoría del período activo.</p></div><?php endif; ?></form></section>
