<?php if ($student): ?><div class="modal fade" id="profileModal" tabindex="-1"><div class="modal-dialog"><form method="post" class="modal-content border-0 shadow"><input type="hidden" name="accion" value="guardar_perfil"><input type="hidden" name="estudiante" value="<?php echo formatos_e($studentId); ?>"><div class="modal-header"><h2 class="modal-title fs-5">Datos complementarios</h2><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><p class="text-muted small">Esta información se usará para completar la contraportada del observador y las planillas.</p><div class="mb-3"><label class="form-label">Condición física o discapacidad</label><input class="form-control" name="condicion_fisica" value="<?php echo formatos_e($student['condicion_fisica']); ?>"></div><div class="row g-3"><div class="col-md-6"><label class="form-label">Grupo</label><input class="form-control" name="grupo" value="<?php echo formatos_e($student['grupo']); ?>"></div><div class="col-md-6"><label class="form-label">Jornada</label><input class="form-control" name="jornada" value="<?php echo formatos_e($student['jornada']); ?>"></div><div class="col-12"><label class="form-label">Grupo sanguíneo y RH</label><input class="form-control" name="tipo_sangre" value="<?php echo formatos_e($student['tipo_sangre']); ?>" placeholder="Ej. O+"></div></div></div><div class="modal-footer"><button class="btn btn-brand">Guardar datos</button></div></form></div></div><?php endif; ?>
<script src="/guagua/comun/vendor/bootstrap/bootstrap.bundle.min.js"></script><script>
document.addEventListener('DOMContentLoaded', function () {
  const academicTab = document.querySelector('[data-bs-target="#informe-academico"]');
  if (academicTab) academicTab.dataset.bsTarget = '#informe-academico-lotes';
  const academicForm = document.querySelector('#informe-academico-lotes form');
  if (academicForm) {
    const table = academicForm.querySelector('table');
    const criterionLegend = academicForm.querySelector('.soft');
    if (criterionLegend) criterionLegend.innerHTML = '<label class="form-label mb-2">Criterios por estudiante</label><p class="small text-muted mb-0">En cada fila marca solo los criterios que correspondan a ese estudiante. Esas opciones se trasladan como X a las columnas del informe.</p><div class="small mt-3"><strong>Est:</strong> dificultad de estudio · <strong>Comp:</strong> competencias · <strong>Act:</strong> comportamiento · <strong>Fam:</strong> acompañamiento familiar · <strong>Aus:</strong> ausencias</div>';
    if (table) {
      const header = table.querySelector('thead tr');
      if (header) header.insertAdjacentHTML('beforeend', '<th style="min-width:270px">Criterios individuales</th>');
      table.querySelectorAll('tbody tr').forEach(function (row) {
        const student = row.querySelector('input[name="estudiantes[]"]'); if (!student) return;
        const criteria = [['dificultad_estudio', 'Est'], ['competencias', 'Comp'], ['comportamiento', 'Act'], ['familia', 'Fam'], ['ausencias', 'Aus']];
        const cell = document.createElement('td'); cell.className = 'small';
        cell.innerHTML = criteria.map(function (criterion) { return '<label class="form-check form-check-inline mb-1"><input class="form-check-input" type="checkbox" name="criterios[' + student.value + '][]" value="' + criterion[0] + '"> <span class="form-check-label">' + criterion[1] + '</span></label>'; }).join('');
        row.appendChild(cell);
      });
      const tools = document.createElement('div'); tools.className = 'd-flex gap-2 mb-2';
      tools.innerHTML = '<button type="button" class="btn btn-sm btn-outline-primary">Seleccionar todos</button><button type="button" class="btn btn-sm btn-outline-secondary">Limpiar selección</button>';
      const buttons = tools.querySelectorAll('button');
      buttons[0].addEventListener('click', function () { table.querySelectorAll('input[name="estudiantes[]"]').forEach(function (box) { box.checked = true; }); });
      buttons[1].addEventListener('click', function () { table.querySelectorAll('input[name="estudiantes[]"]').forEach(function (box) { box.checked = false; }); });
      table.before(tools);
    }
  }
  function copyFields(sourceSelector, targetId) {
    const target = document.getElementById(targetId); if (!target) return;
    document.querySelectorAll('#' + sourceSelector + ' input, #' + sourceSelector + ' textarea').forEach(function (field) {
      if ((field.type === 'radio' || field.type === 'checkbox') && !field.checked) return;
      if (!field.name || field.name === 'accion') return;
      let clone = target.querySelector('[data-copy-name="' + CSS.escape(field.name) + '"]');
      if (!clone) { clone = document.createElement('input'); clone.type = 'hidden'; clone.name = field.name; clone.dataset.copyName = field.name; target.appendChild(clone); }
      clone.value = field.value;
    });
  }
  document.querySelectorAll('[form="observerDownload"]').forEach(function (button) { button.addEventListener('click', function () { copyFields('observerForm', 'observerDownload'); }); });
  document.querySelectorAll('[form="dropoutDownload"]').forEach(function (button) { button.addEventListener('click', function () { copyFields('dropoutForm', 'dropoutDownload'); }); });
  const observerSelect = document.querySelector('#observador select[name="estudiante"]');
  if (observerSelect) {
    const form = observerSelect.closest('form'); form.classList.add('d-none');
    const panel = document.createElement('div'); panel.className = 'mb-4 position-relative';
    panel.innerHTML = '<label class="form-label">Buscar estudiante</label><div class="input-group"><span class="input-group-text bg-white"><i class="bi bi-search"></i></span><input type="search" class="form-control" autocomplete="off" placeholder="Nombre o documento…"></div><div class="list-group position-absolute w-100 shadow-sm mt-1 d-none" style="z-index:5"></div><div class="form-text">Escriba al menos dos caracteres para buscar.</div>';
    form.before(panel);
    const input = panel.querySelector('input'), results = panel.querySelector('.list-group');
    const selected = observerSelect.options[observerSelect.selectedIndex];
    if (selected && selected.value) input.value = selected.textContent.trim();
    let timer;
    input.addEventListener('input', function () {
      clearTimeout(timer); const q = input.value.trim(); results.innerHTML = ''; results.classList.add('d-none');
      if (q.length < 2) return;
      timer = setTimeout(function () {
        fetch('api_estudiantes.php?q=' + encodeURIComponent(q), {headers:{'Accept':'application/json'}})
          .then(function (r) { return r.json(); }).then(function (data) {
            (data.items || []).forEach(function (item) {
              const option = document.createElement('button'); option.type = 'button'; option.className = 'list-group-item list-group-item-action';
              option.innerHTML = '<strong>' + item.nombre.replace(/</g, '&lt;') + '</strong><span class="d-block small text-muted">' + item.id + ' · Grado ' + item.grado + (item.grupo ? ' · Grupo ' + item.grupo : '') + '</span>';
              option.addEventListener('click', function () { window.location.search = 'estudiante=' + encodeURIComponent(item.id); }); results.appendChild(option);
            });
            if (!results.children.length) results.innerHTML = '<div class="list-group-item text-muted small">No se encontraron estudiantes activos.</div>';
            results.classList.remove('d-none');
          }).catch(function () { results.innerHTML = '<div class="list-group-item text-danger small">No fue posible buscar ahora.</div>'; results.classList.remove('d-none'); });
      }, 220);
    });
    document.addEventListener('click', function (event) { if (!panel.contains(event.target)) results.classList.add('d-none'); });
  }
  const now = new Date(); const today = now.toISOString().slice(0,10); const nowTime = now.toTimeString().slice(0,5);
  const commission = document.querySelector('#comision form');
  const sessionDefaults = <?php echo json_encode(['id'=>(string)($_SESSION['id_usuario'] ?? ''), 'nombre'=>(string)($_SESSION['nombre_usu'] ?? ''), 'institucion'=>(string)($_SESSION['configuracion_institucion']['nombre_institucion'] ?? '')], JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT); ?>;
  if (commission) { const sede = commission.querySelector('[name="sede"]'), hora = commission.querySelector('[name="hora"]'), director = commission.querySelector('[name="director"]'); if (sede && !sede.value) sede.value = sessionDefaults.institucion; if (hora && !hora.value) hora.value = nowTime; if (director && !director.value) director.value = sessionDefaults.nombre; }
  const permission = document.querySelector('#permiso form');
  if (permission) { const docente = permission.querySelector('[name="docente"]'), documento = permission.querySelector('[name="documento"]'), fecha = permission.querySelector('[name="fecha_ausencia"]'); if (documento && !documento.value) documento.value = docente?.value || sessionDefaults.id; if (docente) docente.addEventListener('change', () => { if (documento) documento.value = docente.value; }); if (fecha && !fecha.value) fecha.value = today; }
  const recoveryForm = document.querySelector('#refuerzo form');
  if (recoveryForm) {
    const dbaValues = <?php echo json_encode(array_values(array_column($recovery, 'dba')), JSON_UNESCAPED_UNICODE); ?>;
    const competenceInputs = recoveryForm.querySelectorAll('input[name$="[competencia]"]');
    competenceInputs.forEach(function (input, index) { if (!input.value && dbaValues[index]) input.value = dbaValues[index]; });
    const table = recoveryForm.querySelector('table');
    if (table) {
      const controls = document.createElement('div'); controls.className = 'd-flex flex-wrap gap-2 align-items-end mb-3 p-3 rounded-3 border bg-light';
      controls.innerHTML = '<div><label class="form-label small mb-1">Actividad para todos</label><select class="form-select form-select-sm" name="actividad_todos"><option value="">Seleccionar…</option><option value="taller">Taller</option><option value="oral">Ev. oral</option><option value="escrita">Ev. escrita</option><option value="otra">Otra</option></select></div><label class="form-check mb-1"><input class="form-check-input" type="checkbox" name="aplicar_todos" checked> <span class="form-check-label">Aplicar a todos los seleccionados</span></label><span class="small text-muted mb-1">La opción escogida se marca con X en el formato original.</span>';
      table.before(controls);
      table.querySelectorAll('tbody tr').forEach(function (tr) {
        const input = tr.querySelector('input[name$="[competencia]"]'); if (!input) return;
        const activity = document.createElement('select'); activity.className = 'form-select form-select-sm mt-2'; activity.name = input.name.replace('[competencia]', '[actividad]');
        activity.innerHTML = '<option value="">Actividad individual…</option><option value="taller">Taller</option><option value="oral">Ev. oral</option><option value="escrita">Ev. escrita</option><option value="otra">Otra</option>';
        input.after(activity);
      });
    }
  }
});
</script></body></html>
